with src as (
    select KEY_HASH, PARENT_KEY_HASH from {{ ref('stg_clm_pch_pv') }}
)

select
    src.KEY_HASH as KEY_HASH,
    case when w035._N035 = 1 then w035._V035 else null end as W035_CLAIM_NUMBER,
    w035._N035 as W035_N
from src
left join (
    select
        c0.KEY_HASH as _JK035,
        count(*) as _N035,
        max(d0.CLAIM_NUMBER) as _V035
    from {{ ref('hop_clm_pch') }} c0
    join {{ ref('hop_clm') }} c1
        on c0.PARENT_KEY_HASH = c1.KEY_HASH   /* real level 1 */
